{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_distance = case['core_distance']
    distances = case['distances']

    # Validate nodes and core distances
    node_set = set(nodes)
    if not node_set:
        raise ValueError('Nodes list is empty')
    for n in nodes:
        if n not in core_distance:
            raise ValueError(f'Missing core distance for node {n}')

    # Build edges with mutual reachability
    edges = []
    for u, v, d in distances:
        if u not in node_set or v not in node_set:
            raise ValueError(f'Unknown node in distance pair: {u}, {v}')
        mr = max(core_distance[u], core_distance[v], d)
        # Canonicalize: ensure u <= v lexicographically
        if u > v:
            u, v = v, u
        edges.append((mr, u, v))

    # Sort by mutual reachability, then endpoint IDs
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Kruskal with union-find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for mr, u, v in edges:
        if len(mst_edges) == len(nodes) - 1:
            break
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Input graph is disconnected; cannot form MST')

    return {
        'edges': mst_edges,
        'total_weight': total_weight
    }"
}
